if (element.dataset.customReplaced === 'radar') return;
element.dataset.customReplaced = 'radar';

element.style.cssText = 'background:#0d1b2a;border-radius:12px;overflow:hidden;padding:0;box-shadow:0 4px 18px rgba(0,0,0,0.35);';

element.innerHTML = '';

// Header
const header = document.createElement('div');
header.style.cssText = 'display:flex;align-items:center;gap:10px;padding:14px 18px 10px;background:#0d1b2a;border-bottom:1px solid #1e3a5f;';

const radarIcon = document.createElement('span');
radarIcon.textContent = '📡';
radarIcon.style.fontSize = '22px';

const title = document.createElement('h2');
title.textContent = 'Live Weather Radar';
title.style.cssText = 'margin:0;font-size:17px;font-weight:700;color:#7ecfff;letter-spacing:.4px;';

const badge = document.createElement('span');
badge.textContent = 'LIVE';
badge.style.cssText = 'margin-left:auto;background:#e83535;color:#fff;font-size:10px;font-weight:800;padding:2px 7px;border-radius:20px;letter-spacing:1px;animation:none;';

header.appendChild(radarIcon);
header.appendChild(title);
header.appendChild(badge);
element.appendChild(header);

// Radar iframe wrapper
const mapWrap = document.createElement('div');
mapWrap.style.cssText = 'position:relative;width:100%;padding-bottom:56.25%;background:#000;';

const iframe = document.createElement('iframe');
iframe.src = 'https://embed.windy.com/embed2.html?lat=39.5&lon=-98.35&detailLat=39.5&detailLon=-98.35&width=650&height=450&zoom=4&level=surface&overlay=radar&product=radar&menu=&message=&marker=&calendar=now&pressure=&type=map&location=coordinates&detail=&metricWind=mph&metricTemp=%C2%B0F&radarRange=-1';
iframe.title = 'Live Weather Radar Map';
iframe.setAttribute('frameborder', '0');
iframe.setAttribute('allowfullscreen', '');
iframe.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;border:none;';

mapWrap.appendChild(iframe);
element.appendChild(mapWrap);

// Footer note
const note = document.createElement('p');
note.textContent = '🗺️ Powered by Windy — Interactive live precipitation & storm radar';
note.style.cssText = 'margin:0;padding:8px 18px;font-size:11px;color:#5a8fbb;background:#0d1b2a;text-align:center;border-top:1px solid #1e3a5f;';
element.appendChild(note);

if (element.dataset.customReplaced === 'hourly') return;
element.dataset.customReplaced = 'hourly';

element.style.cssText = 'background:#0d1b2a;border-radius:12px;overflow:hidden;padding:0;box-shadow:0 4px 18px rgba(0,0,0,0.35);';

element.innerHTML = '';

// Header
const header = document.createElement('div');
header.style.cssText = 'display:flex;align-items:center;gap:10px;padding:14px 18px 10px;background:#0d1b2a;border-bottom:1px solid #1e3a5f;';

const icon = document.createElement('span');
icon.textContent = '🕐';
icon.style.fontSize = '22px';

const title = document.createElement('h2');
title.textContent = 'Hourly Meteorological Tables';
title.style.cssText = 'margin:0;font-size:17px;font-weight:700;color:#7ecfff;letter-spacing:.4px;';

header.appendChild(icon);
header.appendChild(title);
element.appendChild(header);

// Description
const desc = document.createElement('p');
desc.textContent = 'Access detailed hour-by-hour atmospheric data from trusted meteorological sources:';
desc.style.cssText = 'margin:0;padding:12px 18px 8px;font-size:13px;color:#a8c8e8;line-height:1.5;background:#0d1b2a;';
element.appendChild(desc);

// Links data
const links = [
  {
    label: '🌡️ NWS Hourly Forecast Table',
    sub: 'National Weather Service — temperature, wind, precip & humidity by hour',
    url: 'https://forecast.weather.gov/MapClick.php?CityName=New+York&state=NY&site=OKX&textField1=40.7128&textField2=-74.0059&unit=0&lg=english&&FcstType=graphical'
  },
  {
    label: '💧 Weather.gov Point Forecast (Tabular)',
    sub: 'Full tabular hourly breakdown: dew point, sky cover, pop, wind speed/direction',
    url: 'https://forecast.weather.gov/MapClick.php?CityName=New+York&state=NY&site=OKX&textField1=40.7128&textField2=-74.0059&FcstType=digital'
  },
  {
    label: '🌬️ Open-Meteo Hourly API Explorer',
    sub: 'Open-source meteorological data — temperature, wind, precipitation & more',
    url: 'https://open-meteo.com/en/docs#latitude=40.71&longitude=-74.01&hourly=temperature_2m,precipitation,windspeed_10m,relativehumidity_2m,weathercode'
  },
  {
    label: '🌊 NOAA Aviation Weather (METAR/TAF)',
    sub: 'Real-time & forecast aeronautical meteorological data tables',
    url: 'https://aviationweather.gov/metar/data?ids=KJFK&format=decoded&hours=24&taf=on&layout=on'
  },
  {
    label: '🛰️ Weather Underground PWS Hourly History',
    sub: 'Personal weather station data — hourly observed conditions & trends',
    url: 'https://www.wunderground.com/hourly/us/ny/new-york-city'
  },
  {
    label: '🌍 ECMWF Open Data Forecast Charts',
    sub: 'European Centre hourly ensemble meteorological model output',
    url: 'https://charts.ecmwf.int/products/medium-mslp-wind850?base_time=latest'
  }
];

const list = document.createElement('div');
list.style.cssText = 'padding:6px 14px 14px;display:flex;flex-direction:column;gap:8px;background:#0d1b2a;';

links.forEach(function(link) {
  const a = document.createElement('a');
  a.href = link.url;
  a.target = '_blank';
  a.rel = 'noopener noreferrer';
  a.style.cssText = 'display:flex;flex-direction:column;gap:3px;padding:10px 14px;background:#122840;border:1px solid #1e3a5f;border-radius:8px;text-decoration:none;transition:background .2s;cursor:pointer;';

  const name = document.createElement('span');
  name.textContent = link.label;
  name.style.cssText = 'font-size:13.5px;font-weight:700;color:#7ecfff;';

  const sub = document.createElement('span');
  sub.textContent = link.sub;
  sub.style.cssText = 'font-size:11.5px;color:#6a9abb;line-height:1.4;';

  a.appendChild(name);
  a.appendChild(sub);

  a.addEventListener('mouseover', function() { a.style.background = '#1a3a5c'; });
  a.addEventListener('mouseout',  function() { a.style.background = '#122840'; });

  list.appendChild(a);
});

element.appendChild(list);

// Footer
const footer = document.createElement('p');
footer.textContent = '🔗 Links open authoritative meteorological data sources in a new tab';
footer.style.cssText = 'margin:0;padding:8px 18px;font-size:11px;color:#5a8fbb;background:#0a1520;text-align:center;border-top:1px solid #1e3a5f;';
element.appendChild(footer);
